export const WPL_PLAYER_COUNT = 2379;

export interface WPLPlayerData {
  id: string;
  name: string;
  age: number;
  country: string;
  role: string;
  bowlingStyle?: BowlingStyle;
  battingHand?: BattingHand;
  battingIQ: number;
  timing: number;
  power: number;
  running: number;
  wicketTaking: number;
  economy: number;
  accuracy: number;
  clutch: number;
  fielding?: number;
  keeping?: number;
  teamId: string;
  isWicketKeeper?: boolean;
}

export function getWPLPlayers(): WPLPlayerData[] {
  return WPL_PLAYERS
    .filter((p): p is typeof p & { teamId: string } => !!p.teamId)
    .map(p => ({
      id: p.id,
      name: p.name,
      age: p.age,
      country: p.country,
      role: p.isWicketKeeper ? p.role : p.role,
      bowlingStyle: p.bowlingStyle,
      battingHand: p.battingHand,
      battingIQ: p.ratings.battingIQ,
      timing: p.ratings.timing,
      power: p.ratings.power,
      running: p.ratings.running,
      wicketTaking: p.ratings.wicketTaking,
      economy: p.ratings.economy,
      accuracy: p.ratings.accuracy,
      clutch: p.ratings.clutch,
      ...(p.ratings.fielding !== undefined ? { fielding: p.ratings.fielding } : {}),
      ...(p.ratings.keeping !== undefined ? { keeping: p.ratings.keeping } : {}),
      teamId: p.teamId,
      isWicketKeeper: p.isWicketKeeper,
    }));
}
